-- Paid pack fetches (t1483; K2 spec section 2). One row per fetch of a DATASET price: `fetch_id` is a UUID and doubles as the `Idempotency-Key` of the one credit it consumes. `lot` is the billing lot the price belongs to (a credit is per account and lot), `buyer_key_id` the first 16 hex of the buyer key's SHA-256 (the id a pack's match ids belong to), and `mode` the billing mode the credit is in.
-- `buyer_key` is the key itself, held only while the fetch is `queued` so the operator's builder can build the pack under it; a built, ready, or failed fetch holds null. `state` is `queued` (waiting for the builder), `built` (a pack is in PACKS under `object_key`), `ready` (handed over: the credit is consumed and the buyer may download until `expires_at`), or `failed` (nothing consumed).
-- A ready row is the hand-over record (fetch id, key id, price, `ready_at`); the sweep only nulls `object_key` once the pack is deleted, so the row stays.
CREATE TABLE pack_fetches (fetch_id TEXT PRIMARY KEY, account TEXT NOT NULL REFERENCES accounts(id), price_ref TEXT NOT NULL, lot TEXT NOT NULL, buyer_key_id TEXT NOT NULL, buyer_key TEXT, mode TEXT NOT NULL CHECK (mode IN ('test', 'live')), state TEXT NOT NULL CHECK (state IN ('queued', 'built', 'ready', 'failed')), object_key TEXT, created_at INTEGER NOT NULL, ready_at INTEGER, expires_at INTEGER) STRICT;
CREATE INDEX pack_fetches_by_account_lot ON pack_fetches (account, lot, state);
CREATE INDEX pack_fetches_by_state ON pack_fetches (state, created_at);
